contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    function run(uint v) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000);
        require(v <= address(c).balance);
        require(address(this).balance >= v);
        uint beforeDeposits = c.depositsCount(); if (__ESBMC_reverted()) return;
        uint beforeBalance = address(c).balance;
        bool reverted;
        c.sendMoney(address(this), v, ""); bool __rev0 = __ESBMC_reverted(); if (__rev0) { reverted = true; } else { reverted = false; }
        assert(!reverted ? (address(c).balance == beforeBalance - v && c.depositsCount() == beforeDeposits) : (address(c).balance == beforeBalance && c.depositsCount() == beforeDeposits));
    }
    receive() external payable {}
}

