// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    SimpleWallet c;

    function setUp() public {
        c = new SimpleWallet();
    }

    function _run(uint256 v) internal {
        vm.deal(address(c), VALUE_CAP);
        vm.assume(v <= address(c).balance);
        vm.assume(address(this).balance >= v);
        uint256 beforeDeposits;
        try c.depositsCount() returns (uint256 __r) { beforeDeposits = __r; } catch { return; }
        uint beforeBalance = address(c).balance;
        bool reverted;
        try c.sendMoney(address(this), v, "") { reverted = false; } catch { reverted = true; }
        assertTrue(!reverted ? (address(c).balance == beforeBalance - v && c.depositsCount() == beforeDeposits) : (address(c).balance == beforeBalance && c.depositsCount() == beforeDeposits));
    }

    function testFuzz_run(uint256 v) public {
        _run(v);
    }

    receive() external payable {}
}
